def main():
    root=Path(__file__).resolve().parents[1];references=set()
    for paper in papers(root):
        rel=paper.relative_to(root).as_posix()
        for ref in image_refs(paper.read_text(encoding='utf-8-sig')):
            target=resolve_image(rel,ref)
            if target is None or target.startswith('!'):raise RuntimeError('Unverifiable image reference: '+rel+' -> '+ref)
            references.add(target)
    errors=[];frames=0;ordered=sorted(references)
    with ThreadPoolExecutor(max_workers=16) as executor:
        # Batches bound queued futures and memory; the per-frame check is unchanged.
        done=0
        for start in range(0,len(ordered),512):
            batch=ordered[start:start+512]
            for count,error in executor.map(lambda rel:decode_one(root,rel),batch):
                frames+=count
                if error:errors.append(error)
            done+=len(batch)
            if done%5120==0 or done==len(ordered):print(f'Pixel decode: {done}/{len(ordered)} images',file=sys.stderr,flush=True)
    print(json.dumps({'unique_images':len(references),'decoded_frames':frames,'failed_images':len(errors),'errors':errors},ensure_ascii=False,indent=2))
    return bool(errors)
if __name__=='__main__':sys.exit(main())

